struct LoginPage {
    let app: XCUIApplication
    var user: XCUIElement { app.textFields["login_user"] }
    var pass: XCUIElement { app.secureTextFields["login_pass"] }

    func logIn(_ u: String, _ p: String) -> HomePage {
        user.tap(); user.typeText(u)
        pass.tap(); pass.typeText(p)
        app.buttons["login_submit"].tap()
        return HomePage(app: app)
    }
}
